starterTemplate:
#include <stdio.h>

/* ── 第一份招牌 ── */

int add(int a, int b) {
    return a + b;
}

/* ── 第二份：照另一本书抄来的同一份招牌 ── */

int add(int a, int b) {
    return a + b;
}

int main(void) {
    printf("结果 %d\n", add({a}, {b}));
    return 0;
}

